fn hex(values: byte[]): str =>
  return values.toHex()

struct Codec =>
  fn render(values: byte[]): str =>
    return values.toHex()

fn main(): void =>
  var values: byte[] = {77b, 97b, 110b}
  var encoder: fn(byte[]): str = hex
  println(encoder(values))
  var codec: Codec = {}
  println(codec.render(values))
  sync var shared: byte[] = {77b, 97b, 110b}
  var mutate: fn(): str = fn(): str =>
    shared[0] = 66b
    return shared.toHex()
  println(mutate())
  println(mutate())
  println(shared.toHex())
